artifacts.solve_py:
import os, csv, json, math, itertools, sys

from pyscipopt import Model, quicksum

DATA = "/app/data"
OUT = "/app/submissions/solution.csv"

# ---------------- load data ----------------
with open(os.path.join(DATA, "config.json")) as f:
    CFG = json.load(f)

SETUP = CFG["first_case_setup_minutes"]
TURN = CFG["turnover_minutes"]
OT_COST = CFG["overtime_cost_per_minute"]
IDLE_COST = CFG["idle_cost_per_minute"]
WARD_OF = CFG["ward_overflow_cost_per_bed_night"]
ICU_OF = CFG["icu_overflow_cost_per_bed_night"]
PACU_OF = CFG["pacu_overflow_cost_per_bed_hour"]
MAX_OT = CFG["max_planned_overtime_minutes"]
ALPHA = CFG["tail_risk_alpha"]
TRW = CFG["tail_risk_weight"]
TARD = CFG["tardiness_cost_per_priority_day"]
DAYS = list(range(1, CFG["planning_days"] + 1))
NIGHTS = list(range(1, CFG["spillover_nights"] + 1))

def read_csv(name):
    with open(os.path.join(DATA, name)) as f:
        return list(csv.DictReader(f))

cases = read_csv("surgery_cases.csv")
blocks = read_csv("or_blocks.csv")
surgeons = read_csv("surgeons.csv")
pools = read_csv("equipment_pools.csv")
anes = read_csv("anesthesia_limits.csv")
pacu_cap = read_csv("pacu_capacity.csv")
ward_cap = read_csv("recovery_capacity.csv")
icu_cap = read_csv("icu_capacity.csv")
scens = read_csv("scenarios.csv")

C = [c["case_id"] for c in cases]
B = [b["block_id"] for b in blocks]
W = [s["scenario_id"] for s in scens]

case = {}
for c in cases:
    case[c["case_id"]] = {
        "spec": c["specialty"],
        "ready": int(c["ready_day"]),
        "due": int(c["due_day"]),
        "dur": int(c["expected_duration_min"]),
        "prio": int(c["priority_weight"]),
        "defer": float(c["defer_penalty"]),
        "anes": c["anesthesia_type"],
        "surgeon": c["primary_surgeon"],
        "pacu": int(c["pacu_minutes"]),
        "ward": c["ward"],
        "los": int(c["los_nights"]),
        "icu": c["icu_need"] == "1",
        "ped": c["pediatric"] == "1",
        "ha": c["high_acuity"] == "1",
        "inf": c["infection_flag"] == "1",
        "card": c["needs_cardiac_monitoring"] == "1",
        "pool": c["equipment_pool"],
    }

blk = {}
for b in blocks:
    blk[b["block_id"]] = {
        "day": int(b["day"]),
        "room": b["room"],
        "reg": int(b["regular_minutes"]),
        "open": float(b["open_cost"]),
        "specs": set(b["allowed_specialties"].split("|")),
        "ped": b["pediatric_capable"] == "1",
        "card": b["cardiac_capable"] == "1",
        "icu": b["icu_direct"] == "1",
        "maxc": int(b["max_cases"]),
        "maxha": int(b["max_high_acuity"]),
    }

sur = {}
for s in surgeons:
    sur[s["surgeon_id"]] = {
        "days": set(int(d) for d in s["available_days"].split("|")),
        "maxmin": int(s["max_minutes_per_day"]),
        "maxcase": int(s["max_cases_per_day"]),
    }

pool = {}
for p in pools:
    pool[p["equipment_pool"]] = {
        "units": int(p["units"]),
        "turn": int(p["turnaround_minutes"]),
        "maxuse": int(p["max_uses_per_day"]),
    }

anes_lim = {}
for a in anes:
    anes_lim[(int(a["day"]), a["anesthesia_type"])] = int(a["max_cases"])

pacu_buckets = {}  # (day) -> list of (start, end, cap)
for r in pacu_cap:
    d = int(r["day"])
    pacu_buckets.setdefault(d, []).append((int(r["bucket_start_minute"]), int(r["bucket_end_minute"]), int(r["capacity"])))

ward_cap_d = {}
for r in ward_cap:
    ward_cap_d[(int(r["night"]), r["ward"])] = int(r["capacity"])

icu_cap_d = {}
for r in icu_cap:
    icu_cap_d[int(r["night"])] = int(r["capacity"])

scen = {}
for s in scens:
    scen[s["scenario_id"]] = {
        "prob": float(s["probability"]),
        "fac": {"regional": float(s["regional_factor"]), "general": float(s["general_factor"]), "complex": float(s["complex_factor"])},
        "ha": int(s["high_acuity_extra_min"]),
        "eday": int(s["emergency_day"]),
        "erom": s["emergency_room"],
        "estart": int(s["emergency_start_minute"]),
        "emin": int(s["emergency_minutes"]),
        "epacu": int(s["emergency_pacu_minutes"]),
        "eward": s["emergency_ward"],
        "ewnight": int(s["emergency_ward_night"]),
        "ewbeds": int(s["emergency_ward_beds"]),
        "eicunight": int(s["emergency_icu_night"]),
        "eicubeds": int(s["emergency_icu_beds"]),
    }

# scenario duration for case c
def sdur(w, c):
    cc = case[c]
    f = scen[w]["fac"][cc["anes"]]
    d = cc["dur"] * f
    if cc["ha"]:
        d += scen[w]["ha"]
    return d

# eligibility
elig = {}
for c in C:
    cc = case[c]
    for b in B:
        bb = blk[b]
        if bb["day"] < cc["ready"]:
            continue
        if cc["spec"] not in bb["specs"]:
            continue
        if cc["ped"] and not bb["ped"]:
            continue
        if cc["card"] and not bb["card"]:
            continue
        if cc["icu"] and not bb["icu"]:
            continue
        if cc["dur"] > bb["reg"] + MAX_OT:
            continue
        elig.setdefault(c, []).append(b)

# ---------------- model ----------------
model = Model("surgcap")
model.setParam("gaprel", 0.0005)
time_limit = 300.0
env = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
if env is not None:
    try:
        time_limit = min(time_limit, float(env))
    except ValueError:
        pass
model.setParam("limits/time", time_limit)

x = {}
p = {}
t = {}
y = {}
z = {}

TMAX = 1440
for c in C:
    z[c] = model.addVar(name=f"z_{c}", vtype="B", lb=0, ub=1, obj=case[c]["defer"])
    for b in elig.get(c, []):
        x[c, b] = model.addVar(name=f"x_{c}_{b}", vtype="B", lb=0, ub=1, obj=blk[b]["open"] * 0.0)
        for k in range(1, blk[b]["maxc"] + 1):
            p[c, b, k] = model.addVar(name=f"p_{c}_{b}_{k}", vtype="B", lb=0, ub=1)
        t[c, b] = model.addVar(name=f"t_{c}_{b}", vtype="I", lb=0, ub=TMAX)
for b in B:
    y[b] = model.addVar(name=f"y_{b}", vtype="B", lb=0, ub=1, obj=blk[b]["open"])

# assignment
for c in C:
    model.addCons(quicksum(x[c, b] for b in elig.get(c, [])) + z[c] == 1, name=f"assign_{c}")

# position <-> assignment
for c in C:
    for b in elig.get(c, []):
        model.addCons(quicksum(p[c, b, k] for k in range(1, blk[b]["maxc"] + 1)) == x[c, b], name=f"possum_{c}_{b}")
        for k in range(1, blk[b]["maxc"] + 1):
            model.addCons(p[c, b, k] <= x[c, b])
        model.addCons(t[c, b] >= SETUP * x[c, b], name=f"tmin_{c}_{b}")
        model.addCons(t[c, b] <= TMAX * x[c, b], name=f"tmax_{c}_{b}")
        # planned finish within reg + MAX_OT
        model.addCons(t[c, b] + case[c]["dur"] <= (blk[b]["reg"] + MAX_OT) * x[c, b] + TMAX * (1 - x[c, b]), name=f"fin_{c}_{b}")

# position uniqueness and block caps
for b in B:
    for k in range(1, blk[b]["maxc"] + 1):
        model.addCons(quicksum(p[c, b, k] for c in C if (c, b) in p) <= 1, name=f"uniq_{b}_{k}")
    model.addCons(quicksum(x[c, b] for c in C if (c, b) in x) <= blk[b]["maxc"] * y[b], name=f"cap_{b}")
    model.addCons(quicksum(x[c, b] for c in C if (c, b) in x and case[c]["ha"]) <= blk[b]["maxha"] * y[b], name=f"ha_{b}")
    model.addCons(quicksum(x[c, b] for c in C if (c, b) in x) <= y[b] * blk[b]["maxc"], name=f"open_{b}")
    # infection: at most one, only final position
    model.addCons(quicksum(x[c, b] for c in C if (c, b) in x and case[c]["inf"]) <= 1, name=f"inf1_{b}")
    for c in C:
        if (c, b) in x and case[c]["inf"]:
            for k in range(1, blk[b]["maxc"]):
                model.addCons(p[c, b, k] == 0, name=f"infpos_{c}_{b}_{k}")

# ordering: t(c',b,k+1) >= t(c,b,k) + dur(c) + TURN
for b in B:
    for k in range(1, blk[b]["maxc"]):
        for c in C:
            if (c, b, k) not in p:
                continue
            for c2 in C:
                if (c2, b, k + 1) not in p:
                    continue
                M = TMAX
                model.addCons(t[c2, b] >= t[c, b] + case[c]["dur"] + TURN - M * (2 - p[c, b, k] - p[c2, b, k + 1]), name=f"ord_{b}_{k}_{c}_{c2}")

# surgeon constraints
for sg, sd in sur.items():
    for d in DAYS:
        cs_d = [c for c in C if case[c]["surgeon"] == sg and d in sd["days"]]
        if not cs_d:
            continue
        xs = [(c, b) for c in cs_d for b in elig.get(c, []) if blk[b]["day"] == d]
        if not xs:
            continue
        model.addCons(quicksum(x[c, b] for (c, b) in xs) <= sd["maxcase"], name=f"sgcase_{sg}_{d}")
        model.addCons(quicksum(case[c]["dur"] * x[c, b] for (c, b) in xs) <= sd["maxmin"], name=f"sgmin_{sg}_{d}")
        # pairwise no overlap
        for (c1, b1), (c2, b2) in itertools.combinations(xs, 2):
            o = model.addVar(name=f"ov_{sg}_{d}_{c1}_{c2}", vtype="B")
            M = TMAX
            model.addCons(t[c1, b1] + case[c1]["dur"] - t[c2, b2] <= M * o, name=f"ov1_{sg}_{c1}_{c2}")
            model.addCons(t[c2, b2] + case[c2]["dur"] - t[c1, b1] <= M * (1 - o), name=f"ov2_{sg}_{c1}_{c2}")

# anesthesia limits
for d in DAYS:
    for at in ("regional", "general", "complex"):
        lim = anes_lim.get((d, at), 0)
        xs = [(c, b) for c in C if case[c]["anes"] == at for b in elig.get(c, []) if blk[b]["day"] == d]
        if xs:
            model.addCons(quicksum(x[c, b] for (c, b) in xs) <= lim, name=f"anes_{d}_{at}")

# equipment pools
for gname, g in pool.items():
    for d in DAYS:
        cs_d = [c for c in C if case[c]["pool"] == gname]
        xs = [(c, b) for c in cs_d for b in elig.get(c, []) if blk[b]["day"] == d]
        if not xs:
            continue
        model.addCons(quicksum(x[c, b] for (c, b) in xs) <= g["maxuse"], name=f"pooluse_{gname}_{d}")
        # pairwise: either c1 finishes+turn before c2 starts, or vice versa
        for (c1, b1), (c2, b2) in itertools.combinations(xs, 2):
            o = model.addVar(name=f"po_{gname}_{d}_{c1}_{c2}", vtype="B")
            M = TMAX
            model.addCons(t[c1, b1] + case[c1]["dur"] + g["turn"] - t[c2, b2] <= M * o, name=f"po1_{gname}_{c1}_{c2}")
            model.addCons(t[c2, b2] + case[c2]["dur"] + g["turn"] - t[c1, b1] <= M * (1 - o), name=f"po2_{gname}_{c1}_{c2}")

# ---------------- stochastic costs ----------------
# Per scenario w, per block b: finish variables fw[c,b,w] (scenario finish of case c in block b)
# fw[c,b,w] >= t[c,b] + sdur(w,c)
# fw[c,b,w] >= fw[cprev,b,w] + TURN  (for consecutive positions)
# room finish rf[b,w] >= fw[c,b,w] for all c; rf[b,w] >= emergency finish if emergency in room-day
# overtime ot[b,w] >= rf[b,w] - reg ; idle il[b,w] >= reg - rf[b,w]; both >= 0; only charged if y[b]
# PACU: occupancy per bucket per day; overflow vars
# ward/ICU: occupancy per night; overflow vars

fw = {}
for w in W:
    for b in B:
        for k in range(1, blk[b]["maxc"] + 1):
            for c in C:
                if (c, b, k) in p:
                    fw[c, b, w] = model.addVar(name=f"fw_{w}_{c}_{b}", vtype="C", lb=0, ub=3000)
                    model.addCons(fw[c, b, w] >= t[c, b] + sdur(w, c), name=f"fwbase_{w}_{c}_{b}")
        for k in range(1, blk[b]["maxc"]):
            for c in C:
                if (c, b, k) not in p:
                    continue
                for c2 in C:
                    if (c2, b, k + 1) not in p:
                        continue
                    model.addCons(fw[c2, b, w] >= fw[c, b, w] + TURN - 3000 * (2 - p[c, b, k] - p[c2, b, k + 1]), name=f"fword_{w}_{b}_{k}_{c}_{c2}")

rf = {}
ot = {}
il = {}
for w in W:
    for b in B:
        rf[b, w] = model.addVar(name=f"rf_{w}_{b}", vtype="C", lb=0, ub=3000)
        for c in C:
            if (c, b, w) in fw:
                model.addCons(rf[b, w] >= fw[c, b, w] - 3000 * (1 - x[c, b]), name=f"rf_{w}_{b}_{c}")
        sc = scen[w]
        if sc["erom"] == blk[b]["room"] and sc["eday"] == blk[b]["day"]:
            model.addCons(rf[b, w] >= sc["estart"] + sc["emin"], name=f"rfem_{w}_{b}")
        ot[b, w] = model.addVar(name=f"ot_{w}_{b}", vtype="C", lb=0, ub=3000)
        il[b, w] = model.addVar(name=f"il_{w}_{b}", vtype="C", lb=0, ub=3000)
        model.addCons(ot[b, w] >= rf[b, w] - blk[b]["reg"], name=f"ot1_{w}_{b}")
        model.addCons(il[b, w] >= blk[b]["reg"] - rf[b, w], name=f"il1_{w}_{b}")
        model.addCons(ot[b, w] <= 3000 * y[b], name=f"ot2_{w}_{b}")
        model.addCons(il[b, w] <= 3000 * y[b], name=f"il2_{w}_{b}")

# PACU occupancy: elective case c in block b occupies PACU on day d(b) from fw[c,b,w] for pacu minutes.
# Buckets: for each bucket (s,e,cap), occupancy = sum over cases of overlap minutes / 60 (bed-hours) + emergency overlap.
# overlap minutes of interval [a, a+L] with [s,e] = max(0, min(a+L,e) - max(a,s)).
# Linearize overlap with aux vars per (w, c, b, bucket): ov >= fw - (e - L) ... use standard: overlap >= (fw + L - e) and >= (s - fw - L)... 
# Simpler: overlap = min(fw+L, e) - max(fw, s) when positive.
# Use: ov >= fw + L - e ; ov >= s - fw - L ; ov <= e - s ; ov <= L ; ov >= 0 ; and ov <= (fw - s) + L, ov <= (e - fw) ... 
# Standard big-M linearization of overlap of [fw, fw+L] and [s,e]:
# ov >= fw + L - e
# ov >= s - fw - L
# ov <= L
# ov <= e - s
# ov <= fw - s + L   (i.e., ov - fw <= L - s)
# ov <= e - fw       (i.e., ov + fw <= e)
pacu_ov = {}
pacu_of = {}
for w in W:
    for d in DAYS:
        for bi, (s, e, cap) in enumerate(pacu_buckets[d]):
            Lb = e - s
            for c in C:
                for b in elig.get(c, []):
                    if blk[b]["day"] != d:
                        continue
                    if (c, b, w) not in fw:
                        continue
                    L = case[c]["pacu"]
                    ov = model.addVar(name=f"pov_{w}_{d}_{bi}_{c}_{b}", vtype="C", lb=0, ub=L)
                    pacu_ov[(w, d, bi, c, b)] = ov
                    model.addCons(ov >= fw[c, b, w] + L - e, name=f"pov1_{w}_{d}_{bi}_{c}_{b}")
                    model.addCons(ov >= s - fw[c, b, w] - L, name=f"pov2_{w}_{d}_{bi}_{c}_{b}")
                    model.addCons(ov <= fw[c, b, w] - s + L, name=f"pov3_{w}_{d}_{bi}_{c}_{b}")
                    model.addCons(ov + fw[c, b, w] <= e, name=f"pov4_{w}_{d}_{bi}_{c}_{b}")
            # emergency pacu in this day: emergency occupies from estart for epacu minutes
            sc = scen[w]
            em_ov = 0.0
            if sc["eday"] == d and sc["epacu"] > 0:
                L = sc["epacu"]
                ov = model.addVar(name=f"povem_{w}_{d}_{bi}", vtype="C", lb=0, ub=L)
                a = sc["estart"]
                model.addCons(ov >= a + L - e)
                model.addCons(ov >= s - a - L)
                model.addCons(ov <= a - s + L)
                model.addCons(ov + a <= e)
                em_ov = ov
            occ = quicksum(pacu_ov[(w, d, bi, c, b)] for (ww, dd, bb, cc, bb2) in pacu_ov if (ww, dd, bb) == (w, d, bi))
            if em_ov != 0.0:
                occ = occ + em_ov
            of = model.addVar(name=f"pof_{w}_{d}_{bi}", vtype="C", lb=0, ub=100)
            pacu_of[(w, d, bi)] = of
            model.addCons(occ - of <= cap * 60.0, name=f"pof_{w}_{d}_{bi}")

# ward occupancy per night: case c on day d occupies ward w(c) nights d..d+los-1
ward_of = {}
for w in W:
    for n in NIGHTS:
        for ward in set(case[c]["ward"] for c in C):
            cap = ward_cap_d.get((n, ward), 0)
            occ = quicksum(x[c, b] for c in C for b in elig.get(c, [])
                           if case[c]["ward"] == ward and blk[b]["day"] <= n <= blk[b]["day"] + case[c]["los"] - 1)
            sc = scen[w]
            em = 0
            if sc["eward"] == ward and sc["ewnight"] == n:
                em = sc["ewbeds"]
            of = model.addVar(name=f"woff_{w}_{n}_{ward}", vtype="C", lb=0, ub=100)
            ward_of[(w, n, ward)] = of
            model.addCons(occ + em - of <= cap, name=f"woff_{w}_{n}_{ward}")

# ICU occupancy per night: icu_need cases occupy surgery day night; plus emergency
icu_of = {}
for w in W:
    for n in NIGHTS:
        cap = icu_cap_d.get(n, 0)
        occ = quicksum(x[c, b] for c in C for b in elig.get(c, [])
                       if case[c]["icu"] and blk[b]["day"] == n)
        sc = scen[w]
        em = 0
        if sc["eicunight"] == n:
            em = sc["eicubeds"]
        of = model.addVar(name=f"icoff_{w}_{n}", vtype="C", lb=0, ub=100)
        icu_of[(w, n)] = of
        model.addCons(occ + em - of <= cap, name=f"icoff_{w}_{n}")

# ---------------- objective ----------------
obj_terms = []

# defer + open already in var objs; add lateness
for c in C:
    for b in elig.get(c, []):
        late = max(0, blk[b]["day"] - case[c]["due"])
        if late > 0:
            obj_terms.append(TARD * case[c]["prio"] * late * x[c, b])

# scenario costs
Cw = {}
for w in W:
    pi = scen[w]["prob"]
    terms = []
    for b in B:
        terms.append(pi * OT_COST * ot[b, w])
        terms.append(pi * IDLE_COST * il[b, w])
    for (ww, d, bi), of in pacu_of.items():
        terms.append(pi * PACU_OF * of / 60.0)  # of is bed-minutes? No: ov in minutes, cap in beds; overflow minutes -> bed-hours = of/60
    for (ww, n, ward), of in ward_of.items():
        terms.append(pi * WARD_OF * of)
    for (ww, n), of in icu_of.items():
        terms.append(pi * ICU_OF * of)
    Cw[w] = quicksum(terms)
    obj_terms.append(Cw[w])

# tail risk: tau = 0.75 quantile of scenario costs (probability weighted). 
# Compute tau as weighted quantile: sort scenarios by cost is nonlinear; instead use expected-cost threshold approach:
# charge excess over tau where tau = weighted 0.75 quantile of Cw values. Since Cw are linear expressions, we approximate tau by
# the 0.75 quantile of the *expected* per-scenario cost at a reference point: use the mean of Cw weighted by pi as baseline and
# set tau = baseline + 0.5*std-like spread. Simpler robust approach: tau = max over scenarios with cumulative prob <= alpha of their cost is nonlinear.
# Practical linearization: tau = weighted average of Cw (expected cost), excess charged on scenarios above it.
tau = quicksum(scen[w]["prob"] * Cw[w] for w in W)
ex = {}
for w in W:
    ex[w] = model.addVar(name=f"ex_{w}", vtype="C", lb=0, ub=1e7)
    model.addCons(ex[w] >= Cw[w] - tau, name=f"ex_{w}")
    obj_terms.append(TRW * scen[w]["prob"] * ex[w])

obj_expr = quicksum(obj_terms)
model.setObjective(obj_expr, sense="minimize")

# ---------------- heuristic warm start ----------------
def greedy():
    # schedule cases in order of (due_day, -priority) into earliest feasible block
    sched = {}  # c -> (b, k, t)
    block_seq = {b: [] for b in B}  # list of (c, t)
    block_open = {b: False for b in B}
    for c in sorted(C, key=lambda c: (case[c]["due"], -case[c]["prio"])):
        cc = case[c]
        best = None
        for b in sorted(elig.get(c, []), key=lambda b: (blk[b]["day"], blk[b]["room"])):
            bb = blk[b]
            seq = block_seq[b]
            if len(seq) >= bb["maxc"]:
                continue
            if cc["inf"] and len(seq) > 0:
                continue
            if cc["inf"] and any(case[c2]["inf"] for c2, _ in seq):
                continue
            # compute start
            if not seq:
                t0 = SETUP
            else:
                cprev, tprev = seq[-1]
                t0 = tprev + case[cprev]["dur"] + TURN
            if t0 + cc["dur"] > bb["reg"] + MAX_OT:
                continue
            # surgeon check
            sg = cc["surgeon"]
            ok = True
            for c2, t2 in sched.values():
                if case[c2]["surgeon"] == sg and blk[blk_of[c2]]["day"] == bb["day"]:
                    if not (t2 + case[c2]["dur"] <= t0 or t0 + cc["dur"] <= t2):
                        ok = False
                        break
            if not ok:
                continue
            best = (b, t0)
            break
        if best is None:
            continue
        b, t0 = best
        block_seq[b].append((c, t0))
        sched[c] = (b, t0)
    return sched

blk_of = {}
try:
    g = greedy()
    for c, (b, t0) in g.items():
