# ---------------- validation ----------------
def validate(sol):
    ok = True
    def fail(msg):
        nonlocal ok
        ok = False
        print("FAIL:", msg)
    # assignment
    for c in C:
        if c not in sol:
            continue
    # per block
    byb = {}
    for c, (b, k, t0) in sol.items():
        byb.setdefault(b, []).append((c, k, t0))
    for b, lst in byb.items():
        bb = blk[b]
        if len(lst) > bb["maxc"]:
            fail(f"block {b} too many cases")
        ks = [k for _, k, _ in lst]
        if len(set(ks)) != len(ks):
            fail(f"block {b} dup sequence")
        ha = sum(1 for c, _, _ in lst if case[c]["ha"])
        if ha > bb["maxha"]:
            fail(f"block {b} high acuity cap")
        infs = [c for c, _, _ in lst if case[c]["inf"]]
        if len(infs) > 1:
            fail(f"block {b} multiple infection")
        if infs and infs[0] not in [c for c, k, _ in lst if k == max(ks)]:
            fail(f"block {b} infection not last")
        lst.sort(key=lambda r: r[1])
        prev = None
        for c, k, t0 in lst:
            if t0 < SETUP:
                fail(f"{c} start before setup")
            if t0 + case[c]["dur"] > bb["reg"] + MAX_OT:
                fail(f"{c} planned overtime exceeded")
            if prev is not None:
                pc, pk, pt = prev
                if t0 < pt + case[pc]["dur"] + TURN:
                    fail(f"{c} ordering violation after {pc}")
            prev = (c, k, t0)
    # surgeon
    for sg in sur:
        for d in DAYS:
            cs = [(c, t0) for c, (b, k, t0) in sol.items() if case[c]["surgeon"] == sg and blk[b]["day"] == d]
            if len(cs) > sur[sg]["maxcase"]:
                fail(f"surgeon {sg} day {d} case cap")
            if sum(case[c]["dur"] for c, _ in cs) > sur[sg]["maxmin"]:
                fail(f"surgeon {sg} day {d} minutes cap")
            for (c1, t1), (c2, t2) in itertools.combinations(cs, 2):
                if not (t1 + case[c1]["dur"] <= t2 or t2 + case[c2]["dur"] <= t1):
                    fail(f"surgeon {sg} overlap {c1}/{c2}")
    # anesthesia
    for d in DAYS:
        for at in ("regional", "general", "complex"):
            cnt = sum(1 for c, (b, k, t0) in sol.items() if case[c]["anes"] == at and blk[b]["day"] == d)
            if cnt > anes_lim.get((d, at), 0):
                fail(f"anesthesia {d} {at} cap")
    # equipment
    for gname in pool:
        for d in DAYS:
            g = pool[gname]
            cs = [(c, t0) for c, (b, k, t0) in sol.items() if case[c]["pool"] == gname and blk[b]["day"] == d]
            if len(cs) > g["maxuse"]:
                fail(f"pool {gname} day {d} uses cap")
            for (c1, t1), (c2, t2) in itertools.combinations(cs, 2):
                if not (t1 + case[c1]["dur"] + g["turn"] <= t2 or t2 + case[c2]["dur"] + g["turn"] <= t1):
                    fail(f"pool {gname} turnaround {c1}/{c2}")
    return ok

ok = validate(sol)
